def list_items(records, owner):
    return [dict(item) for item in records if item["owner"] == owner]

def rename_item(records, owner, item_id, label):
    item = next((item for item in records if item["id"] == item_id and item["owner"] == owner), None)
    if item is None:
        raise LookupError("Item unavailable")
    item["label"] = label
    return dict(item)

