import unittest
import service

class ServiceTests(unittest.TestCase):
    def setUp(self):
        self.records = [{"id": 1, "owner": "alice", "label": "Printer"}, {"id": 2, "owner": "bob", "label": "Camera"}]

    def test_list_scope(self):
        self.assertEqual([item["id"] for item in service.list_items(self.records, "alice")], [1])

    def test_rename_own(self):
        self.assertEqual(service.rename_item(self.records, "alice", 1, "Office printer")["label"], "Office printer")

    def test_rename_other_denied(self):
        with self.assertRaises(LookupError):
            service.rename_item(self.records, "alice", 2, "Changed")
        self.assertEqual(self.records[1]["label"], "Camera")

